mapper.insert:
INSERT INTO ai_chat_session (
    session_id, user_id, agent_id, client_id, message_count,
    first_query, last_response, status, add_memory, create_time, update_time
) VALUES (
    #{sessionId}, #{userId}, #{agentId}, #{clientId}, #{messageCount},
    #{firstQuery}, #{lastResponse}, #{status}, 0, #{createTime}, #{updateTime}
)

mapper.select:
SELECT id, session_id, user_id, agent_id, client_id, message_count,
       first_query, last_response, status, create_time, update_time
FROM ai_chat_session
WHERE user_id = #{userId}
ORDER BY create_time DESC, id DESC
LIMIT #{limit}

SELECT id, session_id, user_id, agent_id, client_id, message_count,
       first_query, last_response, status, create_time, update_time
FROM ai_chat_session
WHERE user_id = #{userId}
  AND (create_time < #{cursorTime}
       OR (create_time = #{cursorTime} AND id < #{cursorId}))
ORDER BY create_time DESC, id DESC
LIMIT #{limit}

mapper.delete:
DELETE FROM ai_chat_session
WHERE user_id = #{userId}
  AND session_id = #{sessionId}
